#include "paths.hpp"
#include "preferences.hpp"
#include "language.hpp"
#include "componentdesign.hpp"
#include <QDialog>
#include <QDialogButtonBox>
#include <QTabWidget>
#include <QFormLayout>
#include <QVBoxLayout>
#include <QCheckBox>
#include <QComboBox>
#include <QSpinBox>
#include <QLineEdit>
#include <QPushButton>
#include <QFileDialog>
#include <QSettings>
#include <QLabel>
#include <QHBoxLayout>
namespace {QString tr(const char* de,const char* en){return Language::text(QString::fromUtf8(Language::current()=="de"?de:en));}}
bool showPreferences(QWidget* parent){
    QSettings settings;QDialog dialog(parent);dialog.setObjectName("preferencesDialog");dialog.setWindowTitle(tr("Einstellungen","Settings"));dialog.resize(650,470);auto* root=new QVBoxLayout(&dialog);root->setContentsMargins(24,20,24,20);root->setSpacing(16);auto* title=new QLabel(tr("Dein Arbeitsplatz","Your workspace"));title->setStyleSheet("font-size:23px;font-weight:600");root->addWidget(title);auto* tabs=new QTabWidget;root->addWidget(tabs,1);
    auto* appearance=new QWidget;auto* visual=new QFormLayout(appearance);visual->setSpacing(18);auto* language=new QComboBox;language->setObjectName("preferencesLanguage");for(const auto& code:Language::codes())language->addItem(Language::nativeName(code),code);language->setCurrentIndex(language->findData(Language::current()));visual->addRow(tr("Sprache","Language"),language);auto* design=new QComboBox;design->setObjectName("preferencesDesign");design->addItem(tr("Blocks · Planung","Blocks · planning"),"blocks");design->addItem(tr("Realistic · flache 2D-Ansicht","Realistic · flat 2D view"),"realistic");design->setCurrentIndex(design->findData(ComponentDesign::current()));visual->addRow(tr("Komponenten Design","Component design"),design);auto* dark=new QCheckBox(tr("Dunkle Oberfläche","Dark appearance"));dark->setChecked(settings.value("darkMode",false).toBool());visual->addRow(dark);auto* sound=new QCheckBox(tr("Ton wiedergeben","Play audio"));sound->setChecked(settings.value("soundEnabled",true).toBool());visual->addRow(sound);auto* animations=new QCheckBox(tr("Dezente Animationen","Subtle animations"));animations->setObjectName("preferencesAnimations");animations->setChecked(settings.value("animationsEnabled",true).toBool());visual->addRow(animations);tabs->addTab(appearance,tr("Darstellung","Appearance"));
    auto* editor=new QWidget;auto* editing=new QFormLayout(editor);editing->setSpacing(18);auto* grid=new QSpinBox;grid->setRange(2,100);grid->setValue(settings.value("gridSize",10).toInt());editing->addRow(tr("Rasterabstand","Grid spacing"),grid);auto* snap=new QCheckBox(tr("Am Raster einrasten (Alt setzt aus)","Snap to grid (Alt bypasses)"));snap->setChecked(settings.value("gridSnap",true).toBool());editing->addRow(snap);auto* save=new QCheckBox(tr("Gespeicherte Projekte jede Minute speichern","Save named projects every minute"));save->setObjectName("preferencesAutosave");save->setChecked(settings.value("localAutosave",true).toBool());editing->addRow(save);auto* hint=new QLabel(tr("Neue Projekte zuerst einmal speichern. Zusätzlich bleiben die 15-Sekunden-Wiederherstellungspunkte aktiv.","Save a new project once first. Separate 15-second recovery snapshots remain active."));hint->setWordWrap(true);editing->addRow(hint);tabs->addTab(editor,tr("Editor und Speichern","Editor and saving"));
    auto* simulation=new QWidget;auto* sim=new QFormLayout(simulation);sim->setSpacing(18);auto* step=new QSpinBox;step->setRange(1,10000);step->setSuffix(" µs");step->setValue(settings.value("analogStepUs",100).toInt());sim->addRow(tr("Maximaler analoger Zeitschritt","Maximum analog time step"),step);auto* compiler=new QLineEdit(AppPaths::compiler());compiler->setObjectName("preferencesCompiler");auto* browse=new QPushButton(tr("Auswählen…","Browse…"));auto* compilerRow=new QWidget;auto* compilerLayout=new QHBoxLayout(compilerRow);compilerLayout->setContentsMargins(0,0,0,0);compilerLayout->addWidget(compiler,1);compilerLayout->addWidget(browse);sim->addRow(tr("Sketch-Compiler","Sketch compiler"),compilerRow);QObject::connect(browse,&QPushButton::clicked,&dialog,[&]{auto path=QFileDialog::getOpenFileName(&dialog,tr("g++ wählen","Choose g++"));if(!path.isEmpty())compiler->setText(path);});tabs->addTab(simulation,tr("Simulation","Simulation"));
    auto* buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Save)->setText(tr("Speichern","Save"));buttons->button(QDialogButtonBox::Cancel)->setText(tr("Abbrechen","Cancel"));root->addWidget(buttons);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(compiler->text().trimmed().isEmpty()){compiler->setFocus();return;}dialog.accept();});QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()!=QDialog::Accepted)return false;
    settings.setValue("animationsEnabled",animations->isChecked());settings.setValue("language",language->currentData());settings.setValue("componentDesign",design->currentData());settings.setValue("darkMode",dark->isChecked());settings.setValue("soundEnabled",sound->isChecked());settings.setValue("gridSize",grid->value());settings.setValue("gridSnap",snap->isChecked());settings.setValue("localAutosave",save->isChecked());settings.setValue("analogStepUs",step->value());if(!AppPaths::bundledCompiler().isEmpty()&&compiler->text().trimmed()==AppPaths::bundledCompiler())settings.remove("compiler");else settings.setValue("compiler",compiler->text().trimmed());return true;
}
